contract InvMutTest {

    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(address receiver, uint amount) public {
        require(amount > 0);
        require(receiver == address(0));
        bool succeeded = false;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            succeeded = false;
        } else {
            succeeded = true;
        }
        assert(!succeeded);
    }

    receive() external payable {}
    fallback() external payable {}
}

